```sql
alter table public.friendships enable row level security;
alter table public.posts enable row level security;

create function public.is_friend(p_user uuid, p_other uuid)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select exists (
    select 1 from public.friendships f
    where (f.requester_id = p_user and f.addressee_id = p_other)
       or (f.requester_id = p_other and f.addressee_id = p_user)
      and f.status = 'accepted'
  );
$$;

create function public.posts_guard_author()
returns trigger
language plpgsql
set search_path = public, pg_temp
as $$
begin
  if auth.role() = 'service_role' then
    return new;
  end if;
  if new.author_id is distinct from old.author_id then
    raise exception 'posts author cannot be changed';
  end if;
  return new;
end;
$$;

create trigger posts_guard_author
before update on public.posts
for each row execute function public.posts_guard_author();

create policy posts_select
on public.posts
for select
to anon, authenticated
using (
  audience = 'public'
  or author_id = auth.uid()
  or public.is_friend(auth.uid(), author_id)
);

create policy posts_insert
on public.posts
for insert
to authenticated
with check (author_id = auth.uid());

create policy posts_update
on public.posts
for update
to authenticated
using (author_id = auth.uid())
with check (author_id = auth.uid());

create policy posts_delete
on public.posts
for delete
to authenticated
using (author_id = auth.uid());

create policy friendships_select
on public.friendships
for select
to authenticated
using (requester_id = auth.uid() or addressee_id = auth.uid());

create policy friendships_insert
on public.friendships
for insert
to authenticated
with check (requester_id = auth.uid() and status = 'pending');

create policy friendships_update
on public.friendships
for update
to authenticated
using (status = 'pending' and addressee_id = auth.uid())
with check (status = 'accepted' and addressee_id = auth.uid() and requester_id <> auth.uid());

create policy friendships_delete
on public.friendships
for delete
to authenticated
using (requester_id = auth.uid() or addressee_id = auth.uid());

revoke all on public.friendships, public.posts from anon;
grant select on public.friendships, public.posts to anon;

revoke all on public.friendships, public.posts from authenticated;
grant select, insert, update, delete on public.friendships to authenticated;
grant select, insert, update, delete on public.posts to authenticated;

grant all on public.friendships, public.posts to service_role;

revoke all on function public.is_friend(uuid, uuid) from public, anon;
grant execute on function public.is_friend(uuid, uuid) to authenticated, service_role;

revoke all on function public.posts_guard_author() from public, anon;
grant execute on function public.posts_guard_author() to authenticated, service_role;
