alter table public.friendships enable row level security;
alter table public.posts enable row level security;

create function public.is_friend(p_user uuid, p_other uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1 from public.friendships f
    where (f.requester_id = p_user and f.addressee_id = p_other)
       or (f.requester_id = p_other and f.addressee_id = p_user)
      and f.status = 'accepted'
  );
$$;

create function public.enforce_friendship_update()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if auth.role() = 'service_role' then
    return new;
  end if;
  if new.requester_id <> old.requester_id or new.addressee_id <> old.addressee_id then
    raise exception 'friendship participants cannot be changed';
  end if;
  if old.status = 'accepted' then
    raise exception 'accepted friendships cannot be modified';
  end if;
  if new.status <> 'accepted' then
    raise exception 'only the addressee can accept a request';
  end if;
  if old.requester_id = old.addressee_id then
    raise exception 'cannot accept your own request';
  end if;
  if new.requester_id <> auth.uid() and new.addressee_id <> auth.uid() then
    raise exception 'only the addressee can accept a request';
  end if;
  return new;
end;
$$;

create trigger friendships_guard
before update on public.friendships
for each row execute function public.enforce_friendship_update();

create policy posts_select
on public.posts
for select
to anon, authenticated
