alter table public.requests enable row level security;
alter table public.request_photos enable row level security;

create function public.is_resident(p_unit_id bigint)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (select 1 from public.residents r where r.unit_id = p_unit_id and r.user_id = auth.uid())
$$;

create function public.is_staff(p_building_id bigint)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (select 1 from public.building_staff s where s.building_id = p_building_id and s.user_id = auth.uid())
$$;

create function public.request_status_immutable(p_request_id bigint, p_status text)
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if auth.role() = 'service_role' or current_user = 'service_role' then
    return new;
  end if;
  if new.id is distinct from old.id or new.unit_id is distinct from old.unit_id or new.created_by is distinct from old.created_by or new.description is distinct from old.description then
    raise exception 'only status can be updated on requests';
  end if;
  if not exists (select 1 from public.building_staff s where s.building_id = old.unit_id and s.user_id = auth.uid()) then
    raise exception 'only building staff can update request status';
  end if;
  return new;
end
$$;

create trigger request_status_immutable_trigger
before update on public.requests
for each row execute function public.request_status_immutable(old.id, new.status);

create policy units_select
on public.units
for select
to authenticated
using (public.is_resident(id) or public.is_staff(building_id));

create policy requests_select
on public.requests
for select
to authenticated
using (public.is_resident(unit_id) or public.is_staff(building_id));

create policy requests_insert
on public.requests
for insert
to authenticated
with check (created_by = auth.uid() and status = 'open' and public.is_resident(unit_id));

create policy requests_update
on public.requests
for update
to authenticated
using (public.is_staff(building_id))
with check (public.is_staff(building_id));

create policy request_photos_select
on public.request_photos
for select
to authenticated
using (exists (select 1 from public.requests r where r.id = request_photos.request_id and (public.is_resident(r.unit_id) or public.is_staff(r.unit_id))));

create policy request_photos_insert
on public.request_photos
for insert
to authenticated
with check (exists (select 1 from public.requests r where r.id = request_photos.request_id and (public.is_resident(r.unit_id) or public.is_staff(r.unit_id))));

revoke all on public.units, public.residents, public.building_staff from anon, authenticated;
revoke all on public.requests, public.request_photos from anon, authenticated;

grant select on public.units, public.requests, public.request_photos to authenticated;
grant insert, update on public.requests to authenticated;
grant insert on public.request_photos to authenticated;

grant all on public.units, public.residents, public.building_staff, public.requests, public.request_photos to service_role;

revoke all on function public.is_resident(bigint) from public, anon;
revoke all on function public.is_staff(bigint) from public, anon;
revoke all on function public.request_status_immutable(bigint, text) from public, anon;

grant execute on function public.is_resident(bigint) to authenticated, service_role;
grant execute on function public.is_staff(bigint) to authenticated, service_role;
grant execute on function public.request_status_immutable(bigint, text) to authenticated, service_role;
