alter table public.auctions enable row level security;
alter table public.bids enable row level security;

revoke all on public.auctions from anon, authenticated;
revoke all on public.bids from anon, authenticated;

grant select on public.auctions to authenticated;
grant select on public.bids to authenticated;

create policy "Authenticated can view auctions"
on public.auctions
for select
to authenticated
using (true);

create policy "Sellers can view their auction bids"
on public.bids
for select
to authenticated
using (exists (select 1 from public.auctions a where a.id = bids.auction_id and a.seller_id = auth.uid()));

create policy "Bidders can view their own bids"
on public.bids
for select
to authenticated
using (bidder_id = auth.uid());

create function public.place_bid(p_auction_id bigint, p_amount numeric)
returns numeric
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid uuid := auth.uid();
  v_auction public.auctions%rowtype;
  v_current_highest numeric;
  v_min_inc numeric;
begin
  if v_uid is null then
    raise exception 'Not signed in';
  end if;

  select * into v_auction from public.auctions where id = p_auction_id for update;
  if not found then
    raise exception 'Auction not found';
  end if;

  if v_auction.ends_at <= now() then
    raise exception 'Auction has ended';
  end if;

  if v_auction.seller_id = v_uid then
    raise exception 'Cannot bid on your own auction';
  end if;

  select highest_bid, min_increment into v_current_highest, v_min_inc from public.auctions where id = p_auction_id;

  if v_current_highest is null then
    if p_amount <= v_auction.starting_price then
      raise exception 'Bid too low';
    end if;
  else
    if p_amount <= v_current_highest + v_min_inc then
      raise exception 'Bid too low';
    end if;
  end if;

  insert into public.bids (auction_id, bidder_id, amount) values (p_auction_id, v_uid, p_amount);

  update public.auctions set highest_bid = p_amount, highest_bidder = v_uid where id = p_auction_id;

  return p_amount;
end;
$$;

revoke all on function public.place_bid(bigint, numeric) from public, anon;
grant execute on function public.place_bid(bigint, numeric) to authenticated;
```

